public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {

    // Save the path and query strings from the URI
    String path = u.getPath();
    String query = u.getQuery();

    // Check if the path is an absolute path
    boolean isAbsolutePath = false;
    if (path.startsWith("/")) {
        isAbsolutePath = true;
        path = path.substring(1);
    }

    // Split the path into individual path segments
    String[] segments;
    if (isAbsolutePath) {
        segments = path.split("/");
    } else {
        segments = path.split("/", 2);
    }

    // Create a list to store the decoded path segments
    List<PathSegmentImpl> decodedPathSegments = new ArrayList<>();

    // Decode each path segment and add it to the list
    for (String segment : segments) {
        if (decode) {
            segment = URLDecoder.decode(segment, "UTF-8");
        }
        decodedPathSegments.add(new PathSegmentImpl(segment));
    }

    // Add the query string as an additional path segment if it is present
    if (query != null) {
        if (decode) {
            query = URLDecoder.decode(query, "UTF-8");
        }
        decodedPathSegments.add(new PathSegmentImpl(query));
    }

    return decodedPathSegments;
}

