    // Select the specified row in the JTable
    table.setRowSelectionInterval(row, row);

    // Get the Y coordinate of the specified row
    int rowY = table.getCellRect(row, 0, true).y;

    // Calculate the offset between the row and the top of the JScrollPane viewport
    int rowOffset = rowY - pane.getViewport().getViewPosition().y;

    // Scroll the JScrollPane to the specified row
    if (rowOffset < 0) {
        pane.getVerticalScrollBar().setValue(pane.getVerticalScrollBar().getValue() - rowOffset);
    } else if (rowOffset + rowY > pane.getHeight()) {
        pane.getVerticalScrollBar().setValue(pane.getVerticalScrollBar().getValue() + rowOffset - pane.getHeight() + rowY);
    }

    // Repaint the JTable to ensure that the selected row is properly painted
    table.repaint();
}

